type Theme = 'light' | 'dark';
type WorkspaceId = 'command' | 'crm' | 'sales' | 'finance' | 'operations' | 'people' | 'service' | 'intelligence';

type FormControlSnapshot = {
  control: HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;
  value: string;
  checked?: boolean;
  selectedValues?: string[];
};

type SubmittedFormSnapshot = {
  form: HTMLFormElement;
  controls: FormControlSnapshot[];
};

const currencyFormatter = new Intl.NumberFormat('en-IN', {
  style: 'currency',
  currency: 'INR',
  maximumFractionDigits: 0,
});

const compactCurrencyFormatter = new Intl.NumberFormat('en-IN', {
  style: 'currency',
  currency: 'INR',
  notation: 'compact',
  maximumFractionDigits: 1,
});

const inrNumberFormatter = new Intl.NumberFormat('en-IN', {
  style: 'currency',
  currency: 'INR',
  maximumFractionDigits: 0,
});

const compactInrNumberFormatter = new Intl.NumberFormat('en-IN', {
  style: 'currency',
  currency: 'INR',
  notation: 'compact',
  maximumFractionDigits: 1,
});

const inrFormatter = {
  format(value: number | bigint | undefined): string {
    return typeof value === 'number' || typeof value === 'bigint'
      ? inrNumberFormatter.format(value)
      : 'Restricted';
  },
};

const compactInrFormatter = {
  format(value: number | bigint | undefined): string {
    return typeof value === 'number' || typeof value === 'bigint'
      ? compactInrNumberFormatter.format(value)
      : 'Restricted';
  },
};

function inrOrRestricted(value: number | undefined): string {
  return typeof value === 'number' ? inrFormatter.format(value) : 'Restricted';
}

function compactInrOrRestricted(value: number | undefined): string {
  return typeof value === 'number' ? compactInrFormatter.format(value) : 'Restricted';
}

function hoursOrRestricted(value: number | undefined): string {
  return typeof value === 'number' ? `${value.toFixed(1)}h` : 'Restricted';
}

function countOrRestricted(value: number | undefined): string {
  return typeof value === 'number' ? String(value) : 'Restricted';
}

function sumNumbersOrUndefined(...values: Array<number | undefined>): number | undefined {
  return values.every((value): value is number => typeof value === 'number')
    ? values.reduce((total, value) => total + value, 0)
    : undefined;
}

function formatCurrencyMoney(value: number, rawCurrency: string, compact = false): string {
  const currency = rawCurrency.toUpperCase();
  const localeByCurrency: Record<string, string> = {
    INR: 'en-IN',
    USD: 'en-US',
    EUR: 'de-DE',
    GBP: 'en-GB',
    AED: 'en-AE',
    SGD: 'en-SG',
    AUD: 'en-AU',
    CAD: 'en-CA',
    JPY: 'ja-JP',
  };
  return new Intl.NumberFormat(localeByCurrency[currency] ?? 'en-IN', {
    style: 'currency',
    currency,
    notation: compact ? 'compact' : 'standard',
    maximumFractionDigits: compact ? 1 : 0,
  }).format(value);
}

function formatOpportunityMoney(opportunity: Pick<Opportunity, 'value' | 'currency'>, compact = false): string {
  return formatCurrencyMoney(opportunity.value, opportunity.currency, compact);
}

function stageLabel(
  id: PipelineStageId,
  stages: ReadonlyArray<{ id: PipelineStageId; label: string }> = PIPELINE_STAGES,
): string {
  return stages.find((stage) => stage.id === id)?.label ?? id.replaceAll('-', ' ');
}

function AuthGate({
  configured,
  busy,
  error,
  notice,
  onBootstrap,
  onLogin,
}: {
  configured: boolean;
  busy: boolean;
  error: string;
  notice: string;
  onBootstrap: (input: BootstrapOwnerInput) => Promise<void>;
  onLogin: (input: LoginInput) => Promise<void>;
}): ReactNode {
  const [email, setEmail] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [password, setPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [mfaCode, setMfaCode] = useState('');
  // A live retail operator always starts in a clean, owned workspace. The
  // sample provisioner remains an internal test/demo seam, never a normal
  // production enrollment choice.
  const starterMode = 'clean' as const;
  const [validation, setValidation] = useState('');

  async function submit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    setValidation('');
    if (!configured && password !== confirmation) {
      setValidation('The passwords do not match.');
      return;
    }
    if (configured) {
      await onLogin({ email, password, mfaCode: mfaCode.trim() || undefined });
    } else {
      await onBootstrap({ email, displayName, password, starterMode });
    }
  }

  return (
    <main className="auth-gate">
      <section className="auth-gate__signal" aria-label="Epic BOS security status">
        <div className="brand brand--auth">
          <span className="brand__mark" aria-hidden="true">
            <span /><span /><span />
          </span>
          <div><strong>EPIC</strong><small>Business OS</small></div>
        </div>
        <div className="auth-gate__brief">
          <span className="eyebrow">Secure operating perimeter</span>
          <h1>{configured ? 'Resume command.' : 'Claim the command seat.'}</h1>
          <p>
            {configured
              ? 'Your business controls are protected by a local, revocable session.'
              : 'Create the first owner identity. Your India-first retail workspace starts clean, with no fictional sales, customers, or balances.'}
          </p>
        </div>
        <ol className="security-ledger">
          <li><span>01</span><div><strong>Local-first identity</strong><small>Credentials stay in the business database.</small></div></li>
          <li><span>02</span><div><strong>Hardened derivation</strong><small>Passwords use salted, memory-hard protection.</small></div></li>
          <li><span>03</span><div><strong>Revocable access</strong><small>Lock instantly; sign out to terminate the session.</small></div></li>
        </ol>
        <div className="auth-gate__seal"><ShieldCheck size={18} /><span>Kernel perimeter active</span></div>
      </section>

      <section className="auth-gate__form-panel">
        <div className="auth-form__heading">
          <span className="auth-form__key"><KeyRound size={20} /></span>
          <div>
            <span className="eyebrow">{configured ? 'Operator authentication' : 'First-run enrollment'}</span>
            <h2>{configured ? 'Sign in to Epic BOS' : 'Create the owner account'}</h2>
          </div>
        </div>
        <form className="auth-form" onSubmit={(event) => void submit(event)}>
          {!configured ? <p className="auth-form__clean-start" role="note">You will begin with a clean workspace. Existing data is never changed during account setup.</p> : null}
          {!configured ? (
            <label>
              <span>Owner name</span>
              <input
                required
                minLength={2}
                maxLength={120}
                autoComplete="name"
                value={displayName}
                onChange={(event) => setDisplayName(event.target.value)}
                placeholder="Aarav Shah"
              />
            </label>
          ) : null}
          <label>
            <span>Work email</span>
            <input
              required
              type="email"
              autoComplete="username"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              placeholder="owner@business.in"
            />
          </label>
          <label>
            <span>Password</span>
            <input
              required
              type="password"
              minLength={configured ? 1 : 12}
              maxLength={256}
              autoComplete={configured ? 'current-password' : 'new-password'}
              value={password}
              onChange={(event) => setPassword(event.target.value)}
            />
          </label>
          {configured && (mfaCode.length > 0 || /multi-factor|MFA/iu.test(error)) ? (
            <label>
              <span>Authenticator or recovery code</span>
              <input
                required
                inputMode="numeric"
                autoComplete="one-time-code"
                value={mfaCode}
                onChange={(event) => setMfaCode(event.target.value)}
                placeholder="123456 or recovery code"
                maxLength={64}
              />
              <small className="auth-form__hint">Use the six-digit code from your authenticator app, or one unused recovery code.</small>
            </label>
          ) : null}
          {!configured ? (
            <>
              <label>
                <span>Confirm password</span>
                <input
                  required
                  type="password"
                  minLength={12}
                  maxLength={256}
                  autoComplete="new-password"
                  value={confirmation}
                  onChange={(event) => setConfirmation(event.target.value)}
                />
              </label>
              <p className="password-policy">12+ characters with upper/lower case, a number, and a symbol.</p>
            </>
          ) : null}
          {validation || error ? <p className="auth-form__error" role="alert">{validation || error}</p> : null}
          {notice ? <p className="auth-form__notice" role="status">{notice}</p> : null}
          <button className="button button--primary auth-form__submit" type="submit" disabled={busy}>
            {busy ? (configured ? 'Signing in…' : 'Creating your workspace…') : configured ? 'Enter command center' : 'Enroll owner and continue'}
            <ArrowRight size={17} />
          </button>
        </form>
        <p className="auth-form__footnote">Protected by salted password hashing, optional authenticator MFA, account lockout, and an eight-hour session window.</p>
      </section>
    </main>
  );
}

function PasswordChangeGate({
  session,
  busy,
  error,
  onChange,
  onLogout,
}: {
  session: SessionInfo;
  busy: boolean;
  error: string;
  onChange: (currentPassword: string, newPassword: string) => Promise<void>;
  onLogout: () => Promise<void>;
}): ReactNode {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [validation, setValidation] = useState('');

  async function submit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    if (newPassword !== confirmation) {
      setValidation('The new passwords do not match.');
      return;
    }
    setValidation('');
    await onChange(currentPassword, newPassword);
  }

  return (
    <main className="auth-gate">
      <section className="auth-gate__signal">
        <div className="brand brand--auth"><span className="brand__mark" aria-hidden="true"><span /><span /><span /></span><div><strong>EPIC</strong><small>Business OS</small></div></div>
        <div className="auth-gate__brief"><span className="eyebrow">Credential handoff</span><h1>Make access yours.</h1><p>Temporary credentials cannot enter the operating workspace. Replace the administrator-issued password first.</p></div>
        <div className="auth-gate__seal"><ShieldCheck size={18} /><span>Forced credential rotation</span></div>
      </section>
      <section className="auth-gate__form-panel">
        <div className="auth-form__heading"><span className="auth-form__key"><KeyRound size={20} /></span><div><span className="eyebrow">{session.displayName}</span><h2>Choose a permanent password</h2></div></div>
        <form className="auth-form" onSubmit={(event) => void submit(event)}>
          <label><span>Temporary password</span><input required type="password" autoComplete="current-password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} /></label>
          <label><span>New password</span><input required type="password" minLength={12} maxLength={256} autoComplete="new-password" value={newPassword} onChange={(event) => setNewPassword(event.target.value)} /></label>
          <label><span>Confirm new password</span><input required type="password" minLength={12} maxLength={256} autoComplete="new-password" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label>
          <p className="password-policy">12+ characters with upper/lower case, a number, and a symbol.</p>
          {validation || error ? <p className="auth-form__error" role="alert">{validation || error}</p> : null}
          <button className="button button--primary auth-form__submit" type="submit" disabled={busy}>{busy ? 'Securing…' : 'Replace password and continue'}<ArrowRight size={17} /></button>
          <button className="button button--quiet" type="button" disabled={busy} onClick={() => void onLogout()}>Sign out</button>
        </form>
      </section>
    </main>
  );
}

/**
 * A clean workspace must make the next real operating action obvious instead
 * of filling the command center with fictional transactions or "live" demo
 * controls. Each step routes to an existing, handler-backed workbench.
 */
function CleanWorkspaceOnboardingPanel({
  kernel,
  revenue,
  party,
  onNavigate,
}: {
  kernel: KernelSnapshot;
  revenue: RevenueOpsSnapshot;
  party: PartySnapshot;
  onNavigate: (destination: WorkspaceDestination) => void;
}): ReactNode {
  const company = kernel.companies.find(({ id }) => id === kernel.context.companyId);
  const identityReady = Boolean(
    company?.legalName &&
      company.legalName.trim() &&
      kernel.tenant.name !== 'Your India workspace',
  );
  const tradingProfileReady = Boolean(
    revenue.profile.legalName.trim() && revenue.profile.defaultStateCode,
  );
  const partyReady = party.accounts.length > 0;
  const commercialReady = revenue.products.length > 0 && revenue.taxCodes.length > 0;
  const complete = [identityReady, tradingProfileReady, partyReady, commercialReady]
    .filter(Boolean).length;
  const steps: Array<{
    id: string;
    label: string;
    detail: string;
    ready: boolean;
    action: string;
    icon: LucideIcon;
    destination: WorkspaceDestination;
  }> = [
    {
      id: 'workspace',
      label: 'Name your workspace',
      detail: 'Set the organisation and legal-entity identity that every governed record will inherit.',
      ready: identityReady,
      action: 'Open workspace settings',
      icon: Building2,
      destination: { kind: 'command', surface: 'control' },
    },
    {
      id: 'india-profile',
      label: 'Complete India trading profile',
      detail: 'Capture legal name, state, PAN, and GST status before statutory or invoicing workflows.',
      ready: tradingProfileReady,
      action: 'Open India profile',
      icon: IndianRupee,
      destination: { kind: 'bharat', tab: 'network', workspace: 'intelligence' },
    },
    {
      id: 'customer-master',
      label: 'Create your first customer record',
      detail: 'Start CRM with a real lead, account, contact, or consent record owned by your business.',
      ready: partyReady,
      action: 'Open CRM',
      icon: UsersRound,
      destination: { kind: 'crm-surface', surface: 'party' },
    },
    {
      id: 'catalogue',
      label: 'Set product, HSN/SAC and price policy',
      detail: 'Create only the goods or services you sell, then use their governed GST and commercial evidence.',
      ready: commercialReady,
      action: 'Open catalogue',
      icon: Factory,
      destination: { kind: 'bharat', tab: 'commerce', workspace: 'sales', commerceSurface: 'products' },
    },
  ];

  return (
    <article className="clean-start-panel" data-testid="clean-workspace-onboarding">
      <header className="clean-start-panel__header">
        <div>
          <span className="eyebrow">India-first setup</span>
          <h2>Build your operating foundation</h2>
          <p>
            {complete}/4 essential records are ready. Epic BOS is showing only
            your workspace data; no fictional sales, invoices, employees, or
            statutory records were created.
          </p>
        </div>
        <div className="clean-start-panel__progress" aria-label={`${complete} of 4 setup steps complete`}>
          <strong>{complete}<small>/4</small></strong>
          <span>foundation steps</span>
        </div>
      </header>
      <div className="clean-start-panel__steps">
        {steps.map((step, index) => {
          const Icon = step.icon;
          return (
            <section key={step.id} className="clean-start-step" data-ready={step.ready}>
              <span className="clean-start-step__index">{String(index + 1).padStart(2, '0')}</span>
              <span className="clean-start-step__icon" aria-hidden="true"><Icon size={18} /></span>
              <div className="clean-start-step__copy">
                <strong>{step.label}</strong>
                <small>{step.detail}</small>
              </div>
              <div className="clean-start-step__action">
                <em>{step.ready ? 'Ready' : 'Needs setup'}</em>
                <button type="button" className="button button--quiet" onClick={() => onNavigate(step.destination)}>
                  {step.ready ? 'Review' : step.action}
                </button>
              </div>
            </section>
          );
        })}
      </div>
    </article>
  );
}

