/**
 * A role can still decide which *retail* area is most useful at sign-in, but
 * the first surface must be a plain-language, task-specific workbench.  This
 * prevents a finance, stock, or customer teammate from landing on the old
 * generic CRM dashboard simply because it was the shell's historical
 * default.
 */
function initialRetailShellState(workspace: WorkspaceId): {
  commandSurface: CommandSurface;
  crmSurface: CrmSurface;
  bharatTab: BharatRevenueTab;
} {
  switch (workspace) {
    case 'crm':
      return { commandSurface: 'overview', crmSurface: 'party', bharatTab: 'commerce' };
    case 'sales':
      return { commandSurface: 'overview', crmSurface: 'party', bharatTab: 'commerce' };
    case 'finance':
      return { commandSurface: 'overview', crmSurface: 'party', bharatTab: 'cash' };
    case 'operations':
      return { commandSurface: 'overview', crmSurface: 'party', bharatTab: 'warehouse' };
    case 'people':
      return { commandSurface: 'overview', crmSurface: 'party', bharatTab: 'people' };
    case 'service':
      return { commandSurface: 'overview', crmSurface: 'party', bharatTab: 'delivery' };
    case 'intelligence':
      return { commandSurface: 'overview', crmSurface: 'party', bharatTab: 'intelligence' };
    case 'command':
      return { commandSurface: 'overview', crmSurface: 'party', bharatTab: 'commerce' };
  }
}

