  async function applyRetailDemoReset(
    input: ApplyBakalooRetailDemoResetInput,
  ): Promise<void> {
    setRetailDemoResetBusy(true);
    setRetailDemoResetMessage('');
    try {
      const result = await window.epicBos.retailWorkspace.applyDemoReset(input);
      setRetailDemoResetMessage(result.message);
      if (result.applied) {
        // The main process has already rehydrated every store. Reloading the
        // renderer clears the previous generic dashboard state while retaining
        // the active authenticated session in the same Electron window.
        window.setTimeout(() => window.location.reload(), 450);
        return;
      }
      setRetailDemoResetPreview(
        await window.epicBos.retailWorkspace.getDemoResetPreview(),
      );
    } catch (resetError) {
      setRetailDemoResetMessage(
        resetError instanceof Error
          ? resetError.message
          : 'The retail starter cleanup could not be completed.',
      );
    } finally {
      setRetailDemoResetBusy(false);
    }
  }

